<!DOCTYPE html><html><head><title>Invoice {{ $sale->number }}</title><style>body{font-family:Arial;margin:40px}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #ddd;padding:10px;text-align:left}.right{text-align:right}@media print{button{display:none}}</style></head><body><button onclick='window.print()'>Cetak</button><h1>INVOICE</h1><p>{{ $sale->number }} � {{ $sale->date->format('d/m/Y') }}</p><p>Kepada: <b>{{ $sale->customer->name }}</b></p><table><tr><th>Produk</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr>@foreach($sale->items as $item)<tr><td>{{ $item->product->name }}</td><td>{{ $item->quantity }}</td><td>Rp {{ number_format((float)$item->price,0,',','.') }}</td><td>Rp {{ number_format((float)$item->subtotal,0,',','.') }}</td></tr>@endforeach</table><h2 class='right'>Total: Rp {{ number_format((float)$sale->total,0,',','.') }}</h2><p class='right'>Sisa: Rp {{ number_format($sale->outstandingBalance(),0,',','.') }}</p></body></html>
